'use strict';
// V58.2 — transitions et validation annuelle des contrats d'entraineur (moteur pur).
(function(root,factory){const api=factory(typeof module==='object'&&module.exports?require('./coach-negotiations.js'):root.CDCoachNegotiations);if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDCoachContractCycle=api})(typeof globalThis==='object'?globalThis:null,function(neg){
const copy=x=>JSON.parse(JSON.stringify(x));const requireValid=(v,m)=>{if(!v)throw Error(m)};
function audit(state){neg.validate(state);const active=state.contracts.filter(x=>x.status==='active');requireValid(active.length<=1,'Plusieurs contrats actifs');for(const c of state.contracts){requireValid(typeof c.clubId==='string'&&c.clubId&&Number.isInteger(c.from)&&Number.isInteger(c.until)&&c.until>c.from&&Number.isFinite(c.salary)&&c.salary>=0,'Contrat invalide');}return {active:active.length,contracts:state.contracts.length,offers:state.offers.length,events:state.events.length};}
function transition(state,season){audit(state);requireValid(Number.isInteger(season)&&season>=1,'Saison invalide');const n=copy(state);for(const o of n.offers){if(o.status==='pending'&&o.expires<season){o.status='expired';n.events.push({type:'offerExpired',season,offerId:o.id});}}for(const c of n.contracts){if(c.status==='active'&&c.until<=season){c.status='completed';n.history.push({clubId:c.clubId,end:season,reason:'contractEnd'});n.events.push({type:'contractEnd',season,clubId:c.clubId});}}audit(n);return n;}
function negotiate(state,offerId,salary,years,season,cap){audit(state);requireValid(Number.isFinite(cap)&&cap>=0,'Plafond invalide');const o=state.offers.find(x=>x.id===offerId);requireValid(o&&o.status==='pending'&&o.expires>=season,'Offre indisponible');const n=neg.apply(state,{type:'counter',offerId,salary,years,season}).state;const response={offerId,season,accepted:salary<=cap,cap};if(!response.accepted){n.events.push({type:'counterDeclined',season,offerId,cap});n.offers.find(x=>x.id===offerId).counter=null;}else n.events.push({type:'counterApproved',season,offerId});audit(n);return {state:n,response};}
function sign(state,offerId,season,cap){const current=transition(state,season);const candidate=current.offers.find(x=>x.id===offerId);requireValid(candidate&&candidate.status==='pending','Offre expiree');return neg.apply(current,{type:'accept',offerId,season,salaryCap:cap}).state;}
function dismiss(state,season){const n=neg.apply(state,{type:'dismiss',season}).state;audit(n);return n;}
function resign(state,season){const n=neg.apply(state,{type:'resign',season}).state;audit(n);return n;}
function apply(state,clubId,season){audit(state);return neg.apply(state,{type:'apply',clubId,season}).state;}
return Object.freeze({audit,transition,negotiate,sign,dismiss,resign,apply});});
